10	export function formatCurrency(value: number, currency: string = "BRL"): string {
11	  return new Intl.NumberFormat("pt-BR", {
12	    style: "currency",
13	    currency,
14	  }).format(value)
15	}
16	
17	export function formatDate(date: string | Date, fmt: string = "dd/MM/yyyy"): string {
18	  const d = typeof date === "string" ? parseISO(date) : date
19	  return format(d, fmt, { locale: ptBR })
20	}
