22	export function formatHours(hours: number): string {
23	  const h = Math.floor(hours)
24	  const m = Math.round((hours - h) * 60)
25	  if (m === 0) return `${h}h`
26	  return `${h}h${m.toString().padStart(2, "0")}`
27	}
28	
29	export function generateInvoiceNumber(sequence: number, year?: number): string {
30	  const y = year ?? new Date().getFullYear()
31	  return `${y}-${sequence.toString().padStart(3, "0")}`
32	}
